#include "contour.hpp"
#include <iostream>
#include <unistd.h>
int main(int argc,char**argv){try{alarm(30);auto data=load_data(argv[1],6);auto fit=read_json(fs::path(argv[1])/"runtime/experiments/native-geometric-replacement-20261020/carla-local-fixed/fit-6.json");M4 coarse=matrix(fit["solve"]["stages"][0]["matrix"]),fine=matrix(fit["solve"]["matrix"]);prepare_support(data.pairs,coarse);double worst=0,maxChange=0,coarseError=0;size_t count=0;json rows=json::array();for(auto&p:data.pairs){auto u0=project(p,coarse),u1=project(p,fine);json chains=json::array();for(size_t k=0;k<p.supported_hull.size();++k)if(std::isfinite(p.allowances[k])){++count;auto a0=projected_allowance(p,k,u0,{},false),a1=projected_allowance(p,k,u1,{},false);maxChange=std::max(maxChange,std::abs(a1.first-a0.first));coarseError=std::max(coarseError,std::abs(a0.first-p.allowances[k]));chains.push_back({{"hullIndex",p.supported_hull[k]},{"chain",p.spacing_chains[k]},{"normal",{p.spacing_normals[k].x(),p.spacing_normals[k].y()}},{"coarseAllowance",a0.first},{"previousBestAllowance",a1.first}});}rows.push_back({{"id",p.id},{"chains",chains}});for(M4 T:std::vector<M4>{coarse,fine}){auto e=contour_term(p,project(p,T),jacobian(p,T),true);for(int a=0;a<6;++a){Vec7 d=Vec7::Zero();double h=1e-6;d[a]=h*units[a];double plus=contour_term(p,project(p,delta(d)*T),{},false).value,minus=contour_term(p,project(p,delta(-d)*T),{},false).value;double fd=(plus-minus)/(2*h);worst=std::max(worst,std::abs(fd-e.gradient[a])/(1+std::abs(fd)));}}}if(coarseError>1e-12||worst>1e-5)throw std::runtime_error("coarse/FD check");verify_sources(data.provenance);json report={{"passed",true},{"referenceRead",false},{"supported",count},{"maxAllowanceChangePixels",maxChange},{"coarseError",coarseError},{"relativeFD",worst},{"supports",rows}};std::ofstream(argv[2])<<report.dump(2);report.erase("supports");std::cout<<report.dump(2)<<std::endl;}catch(std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
